/* Presentation layer. All arithmetic is in core.js; all large-group data are reproducible. */
(() => {
 'use strict';
 const D=window.MATHIEU_DATA,M=window.Mathieu,$=s=>document.querySelector(s);
 const chapters=[['overview','Five exceptional groups'],['permutations','Permutations & words'],['designs','Designs & completion'],['orders','Orders without enumeration'],['sylow','Sylow subgroups'],['triangles','Triangle quotients'],['codes','Golay codes & decoding'],['representations','Representations & invariants'],['methods','Algorithms & evidence']];
 const fmt=n=>Number(n).toLocaleString('en-US'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const gname=n=>'M<sub>'+n+'</sub>',label=(i,n=state.n)=>i===11&&n===12?'∞':i===23&&n===24?'∞':String(i);
 const mathset=(B,n=state.n)=>'{'+B.map(i=>label(i,n)).join(', ')+'}';
 const metric=(v,t)=>`<div class="metric"><b>${v}</b><span>${t}</span></div>`;
 const badge=(text,kind='')=>`<span class="badge ${kind}">${text}</span>`;
 const algorithm=(title,body,code='')=>`<details class="algorithm"><summary>${title}</summary>${body}${code?`<pre><code>${esc(code)}</code></pre>`:''}</details>`;
 const head=(k,title,lead)=>`<div class="scene-head"><div class="kicker">${k}</div><h1>${title}</h1><p class="lead">${lead}</p></div>`;
 const note=(id,text='Read the argument in the notes')=>`<a href="notes/math611_lecture_9_m11_ver2.pdf#nameddest=${id}">${text} ↗</a>`;
 const codeCache={};
 const getWords=name=>codeCache[name]||(codeCache[name]=M.codewords(D.codes[name].basis,D.codes[name].q));
 let state={scene:'overview',n:11},cancelAnimation=()=>{};
 function readHash(){const [scene,q='']=location.hash.slice(1).split('?');const params=new URLSearchParams(q),n=Number(params.get('group'));return {scene:chapters.some(c=>c[0]===scene)?scene:'overview',n:D.groups[n]?n:state.n,subgroup:params.get('subgroup')};}
 function navigate(scene,n=state.n){const hash='#'+scene+'?group='+n;if(location.hash===hash)render();else location.hash=hash;}
 function positions(n){const r=n>12?150:139,cx=220,cy=180;return Array.from({length:n},(_,i)=>[cx+r*Math.cos(-Math.PI/2+2*Math.PI*i/n),cy+r*Math.sin(-Math.PI/2+2*Math.PI*i/n)]);}
 function pointSVG(n,{selected=[],block=[],fixed=[],edges=[],permutation=null,clickable=false}={}){
   const ps=positions(n);let h='<svg class="diagram" viewBox="0 0 440 365" role="img" aria-label="Permutation action on '+n+' labelled points"><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#087b7c"/></marker></defs>';
   if(block.length>1){const poly=block.map(i=>ps[i].join(',')).join(' ');h+=`<polygon points="${poly}" fill="#087b7c" opacity=".07" stroke="#087b7c" stroke-width="2"/>`;}
   for(const [a,b] of edges){const [x,y]=ps[a],[u,v]=ps[b];h+=`<path class="edge" d="M${x},${y} L${u},${v}"/>`;}
   if(permutation)permutation.forEach((j,i)=>{if(i===j)return;const [x,y]=ps[i],[u,v]=ps[j],dx=u-x,dy=v-y,len=Math.hypot(dx,dy),ox=x+16*dx/len,oy=y+16*dy/len,ex=u-18*dx/len,ey=v-18*dy/len;h+=`<path class="cycle-edge" marker-end="url(#arrow)" d="M${ox},${oy} Q${220+(x+u-440)*.08},${180+(y+v-360)*.08} ${ex},${ey}" opacity="${selected.includes(i)?1:.25}"/>`;});
   ps.forEach(([x,y],i)=>{const cs=['point',selected.includes(i)?'selected':'',block.includes(i)?'in-block':'',fixed.includes(i)?'fixed':''].join(' ');h+=`<g class="${cs}" transform="translate(${x},${y})" ${clickable?`tabindex="0" role="button" data-point="${i}" aria-label="Point ${label(i,n)}${selected.includes(i)?', selected':''}" aria-pressed="${selected.includes(i)}"`:''}><circle r="${n>12?12.5:15}"/><text text-anchor="middle" dominant-baseline="central">${label(i,n)}</text></g>`;});return h+'</svg>';
 }
 function connectPoints(fn){document.querySelectorAll('[data-point]').forEach(el=>{el.onclick=()=>fn(Number(el.dataset.point));el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn(Number(el.dataset.point));}};});}
 function bars(hist,{total=null,gold=null}={}){const entries=Object.entries(hist).sort((a,b)=>+a[0]-+b[0]),max=Math.max(...entries.map(e=>e[1]));return entries.map(([k,v])=>`<div class="bar-row"><span>${k}</span><div class="bar-track"><div class="bar ${gold==k?'gold':''}" style="width:${100*v/max}%"></div></div><span class="count">${fmt(v)}</span></div>`).join('');}
 function render(){cancelAnimation();state=readHash();$('#group-select').value=state.n;const ci=chapters.findIndex(c=>c[0]===state.scene);$('#chapters').innerHTML=chapters.map(([id,title],i)=>`<a href="#${id}?group=${state.n}" ${id===state.scene?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${title}</a>`).join('');$('#position').textContent=(ci+1)+' / '+chapters.length+' · '+chapters[ci][1];$('#previous').disabled=ci===0;$('#next').disabled=ci===chapters.length-1;$('#notes-link').href='notes/math611_lecture_9_m11_ver2.pdf#nameddest='+state.scene;scenes[state.scene]();$('#announcement').textContent=chapters[ci][1]+', M'+state.n;}
 const scenes={};
 scenes.overview=()=>{const G=D.groups[state.n];$('#stage').innerHTML=head('01 / EXCEPTIONAL SYMMETRY','Small designs. Enormous symmetry.','Start with permutations. Watch a design emerge, calculate its symmetries, and use the same structure to correct errors. The five sporadic Mathieu groups share this story, at two different scales.')+
 `<div class="family">${[11,12,22,23,24].map(n=>`<button class="family-card ${n===state.n?'active':''}" data-group="${n}"><strong>${gname(n)}</strong><small>${fmt(D.groups[n].order)} elements</small><small>S(${D.groups[n].t}, ${D.groups[n].k}, ${n})</small></button>`).join('')}</div>
 <div class="grid"><section class="panel visual"><div class="panel-title"><h2>Two families of point stabilizers</h2>${badge('Classical identifications','cited')}</div><svg class="family-diagram" viewBox="0 0 610 230" role="img" aria-label="M12 has point stabilizer M11; M24 has point stabilizer M23, then M22, then PSL3 of F4"><defs><marker id="family-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0,0 L10,5 L0,10" fill="#087b7c"/></marker></defs><g font-size="29" text-anchor="middle"><text x="82" y="65">M₁₂</text><text x="265" y="65">M₁₁</text><text x="82" y="162">M₂₄</text><text x="265" y="162">M₂₃</text><text x="444" y="162">M₂₂</text><text x="444" y="221" font-size="17">PSL₃(𝔽₄)</text></g><g stroke="#087b7c" marker-end="url(#family-arrow)"><path d="M127,55 H218"/><path d="M127,153 H218"/><path d="M308,153 H397"/><path d="M444,175 V198"/></g><g text-anchor="middle" font-size="11"><text x="173" y="36">fix ∞ · index 12</text><text x="173" y="133">fix ∞ · index 24</text><text x="353" y="133">fix 22 · index 23</text><text x="536" y="193">fix one more point</text></g></svg><p class="small muted">The labels in each family are compatible. The last group is a group of Lie type, not another sporadic group.</p></section>
 <section class="panel"><h2>${gname(state.n)} at a glance</h2><div class="metric-row">${metric(fmt(G.order),'group order')}${metric(G.blocks.length,'design blocks')}${metric(G.t+'-transitive','natural action')}</div><p>A block has ${G.k} points. Every ${G.t}-set belongs to exactly one block. ${state.n<20?'The action is sharply '+G.t+'-transitive: an ordered '+G.t+'-tuple determines a unique group element.':'The action is not sharp: fixing '+G.t+' ordered points leaves '+fmt(G.order/Array.from({length:G.t},(_,i)=>state.n-i).reduce((a,b)=>a*b,1))+' symmetries.'}</p><p class="callout">What can a group preserve without being the whole symmetric group?</p><div class="controls"><button id="start-demo">Explore its permutations →</button></div><p class="small">${note('overview')}</p></section></div>
 <div class="timeline"><div><b>1861 · Mathieu</b><span>Exceptional multiply transitive permutation groups.</span></div><div><b>1873 · Mathieu</b><span>The 24-point, five-fold transitive example.</span></div><div><b>1938 · Witt</b><span>Steiner systems reveal the incidence geometry.</span></div><div><b>1949 · Golay</b><span>Perfect codes connect symmetry with error correction.</span></div></div>`;
 document.querySelectorAll('[data-group]').forEach(el=>el.onclick=()=>navigate('overview',+el.dataset.group));$('#start-demo').onclick=()=>navigate('permutations');};
 scenes.permutations=()=>{const G=D.groups[state.n];let word=G.generator_names[0],start=0,parsed=null,step=0,timer=null;cancelAnimation=()=>clearInterval(timer);
 $('#stage').innerHTML=head('02 / A GROUP OF PERMUTATIONS','A word is a sequence of moves.','Choose a generator or enter a word. Products act from right to left, exactly as in the lecture. The animation tracks one point; the arrows show the current factor on every point.')+
 `<div class="grid"><section class="panel visual"><div class="panel-title"><h2 id="word-title">${gname(state.n)} on ${state.n} points</h2>${badge('Computed in your browser')}</div><div id="perm-figure"></div><p id="trace" class="formula small"></p><div class="controls"><button id="step-word">Step right to left</button><button id="play-word" class="quiet">Play</button><button id="reset-word" class="quiet">Reset</button></div><p class="small muted">Click a point to change the starting point. ${state.n===24?'∞ is the parity coordinate, stored as 23.':state.n===12?'∞ is stored as 11.':'Labels start at 0.'}</p></section>
 <section class="panel"><h2>Compose, invert, compare</h2><div class="chips">${G.generator_names.map((g,i)=>`<button class="pill" data-generator="${i}">${g}</button>`).join('')}</div><label class="small" for="word-input">Word in these generators</label><div class="controls"><input id="word-input" type="text" value="${word}" style="flex:1;min-width:150px" spellcheck="false"><button id="evaluate-word">Evaluate</button></div><p class="small muted">Use spaces, products, and integer powers: <span class="mono">${G.generator_names[0]} ${G.generator_names[1]}^-1</span>. The empty word is 1.</p><div id="word-result"></div><div id="generator-detail" class="small"></div>${algorithm('Algorithm · permutation arrays and cycle decomposition','<p>Store p as the array [p(0), …, p(n−1)]. Composition takes n array lookups. Follow each unvisited point around its cycle; the order is the least common multiple of the cycle lengths. No group enumeration is involved.</p>','compose(a,b)[i] = a[b[i]]\ninverse(a)[a[i]] = i\norder(a) = lcm(length of each disjoint cycle)')}<p class="small">${note('permutations')}</p></section></div>`;
 function show(){try{parsed=M.parseWord(word,G.generator_names,G.generators,G.n);step=0;clearInterval(timer);draw();const p=parsed.permutation;$('#word-result').innerHTML=`<div class="result"><div class="word">${esc(M.cycleText(p,i=>label(i)))}</div><div class="metric-row">${metric(M.order(p),'element order')}${metric(p.filter((x,i)=>x===i).length,'fixed points')}</div></div>`;}catch(e){$('#word-result').innerHTML='<div class="result error">'+esc(e.message)+'</div>';}}
 function draw(){const ts=parsed.tokens.slice().reverse();let a=start,path=[a];for(let i=0;i<step;i++){a=ts[i].permutation[a];path.push(a);}const current=step<ts.length?ts[step].permutation:parsed.permutation;$('#perm-figure').innerHTML=pointSVG(G.n,{selected:[a],permutation:current,clickable:true});connectPoints(i=>{start=i;step=0;draw();});$('#trace').textContent=path.map(i=>label(i)).join(' → ');$('#word-title').innerHTML=step<ts.length?'Next factor: '+esc(ts[step].name)+(ts[step].exponent===1?'':'^'+ts[step].exponent):'Result of '+esc(word||'1');$('#step-word').disabled=step>=ts.length;$('#generator-detail').innerHTML=`<b>${step} / ${ts.length}</b> factors applied. ${step<ts.length?'The rightmost remaining factor acts next.':'The point has reached its image under the complete word.'}`;}
 $('#evaluate-word').onclick=()=>{word=$('#word-input').value;show();};$('#word-input').onkeydown=e=>{if(e.key==='Enter')$('#evaluate-word').click();};document.querySelectorAll('[data-generator]').forEach(el=>el.onclick=()=>{word=G.generator_names[+el.dataset.generator];$('#word-input').value=word;show();});$('#step-word').onclick=()=>{if(step<parsed.tokens.length){step++;draw();}};$('#reset-word').onclick=()=>{clearInterval(timer);step=0;draw();};$('#play-word').onclick=()=>{clearInterval(timer);step=0;draw();timer=setInterval(()=>{if(step>=parsed.tokens.length){clearInterval(timer);return;}step++;draw();},850);};show();};
 scenes.designs=()=>{const G=D.groups[state.n];let biplane=false,selected=[],blockIndex=0,orb=null,orbitStep=0;let timer=null;cancelAnimation=()=>clearInterval(timer);
 $('#stage').innerHTML=head('03 / INCIDENCE GEOMETRY','Complete a small set to a block.','Select points and see every block through them. For a Witt design, the last selected point leaves exactly one possible block. Then let the generators build the whole orbit.')+
 `<div class="grid"><section class="panel visual"><div class="panel-title"><h2 id="design-title"></h2>${badge('Live incidence lookup')}</div>${state.n===11?'<div class="controls"><button id="witt-mode" class="pill active">66 pentads</button><button id="biplane-mode" class="pill">11 residue translates</button></div>':''}<div id="design-figure"></div><div class="controls"><button id="clear-points" class="quiet">Clear selection</button><button id="example-subset" class="quiet">Choose a defining set</button></div><div id="completion"></div><p class="small muted" id="design-instruction"></p></section>
 <section class="panel"><h2 id="blocks-heading"></h2><div id="incidence-stats"></div><label for="block-range" class="small">Inspect a block</label><input type="range" id="block-range" min="0" value="0"><p id="block-label" class="word"></p><h3>Intersections with this block</h3><div id="intersection-bars"></div><p class="small muted">Labels give the intersection size; bar lengths count blocks. The chosen block itself is omitted.</p><div class="controls"><button id="audit-design">Check every defining subset</button></div><div id="audit-result"></div>${algorithm('Algorithm · incidence dictionary','<p>For each block B, visit its t-subsets and increment their counters. A Steiner system is verified when all binomial(n,t) keys occur exactly once. This visits only b·binomial(k,t) incidences: 42,504 for W₂₄.</p>','counts = new Map()\nfor B in blocks:\n  for T in combinations(B,t): counts[T] += 1\nassert all t-subsets appear exactly once')}<p class="small">${note('designs')}</p></section></div>
 <section class="panel"><div class="panel-title"><h2>Build the block orbit</h2>${badge('Breadth-first search')}</div><div class="grid equal"><div><p>Begin with one block. Apply each generator, keep every new block once, and repeat until the queue is exhausted.</p><div class="controls"><button id="orbit-next">Next layer</button><button id="orbit-all" class="quiet">Complete orbit</button><button id="orbit-reset" class="quiet">Reset orbit</button></div><div id="orbit-status" class="result"></div></div><div id="orbit-bars"></div></div>${algorithm('Why the orbit is complete','<p>The final set contains the seed and is closed under every generator. In a finite permutation action it is also closed under their inverses. It is therefore the whole orbit. A hash set prevents revisiting blocks; the queue records their shortest generator distance from the seed.</p>')}</section>`;
 function model(){return biplane?{blocks:D.biplane,t:2,k:5,n:11,name:'The residue biplane',gens:[D.groups[11].generators[0]]}:{...G,name:'The Witt design W'+state.n,gens:G.generators};}
 function draw(){const d=model(),B=d.blocks[blockIndex],matches=d.blocks.filter(B=>selected.every(i=>B.includes(i)));const chosen=selected.length?matches[0]||[]:B;$('#design-title').textContent=biplane?'2-(11,5,2) biplane':`S(${d.t}, ${d.k}, ${d.n})`;$('#blocks-heading').textContent=d.name;$('#design-figure').innerHTML=pointSVG(d.n,{selected,block:chosen,clickable:true});connectPoints(i=>{if(selected.includes(i))selected=selected.filter(x=>x!==i);else{if(selected.length===d.t)selected=[];selected.push(i);}draw();});$('#completion').innerHTML=`<div class="result"><b>${fmt(matches.length)}</b> ${matches.length===1?'block':'blocks'} through ${selected.length?mathset(selected):'the empty set'}.${selected.length===d.t?'<br>'+ (biplane?'Two translates contain this pair.':`Unique completion: <b>${mathset(matches[0])}</b>.`):''}</div>`;$('#design-instruction').textContent=`Select up to ${d.t} points. Dark points are selected; green points show ${selected.length?'the first compatible':'the inspected'} block.`;$('#incidence-stats').innerHTML=`<div class="metric-row">${metric(d.blocks.length,'blocks')}${metric(d.k,'points per block')}${metric(biplane?'2':'1','blocks through a '+d.t+'-set')}</div>`;$('#block-range').max=d.blocks.length-1;$('#block-range').value=blockIndex;$('#block-label').textContent=`Block ${blockIndex+1} / ${d.blocks.length}: ${mathset(B)}`;const hist=M.histogram(d.blocks.filter((_,i)=>i!==blockIndex).map(C=>C.filter(i=>B.includes(i)).length));$('#intersection-bars').innerHTML=bars(hist);}
 function resetOrbit(){const d=model();orb=M.blockOrbit(d.blocks[0],d.gens);orbitStep=0;showOrbit();}
 function showOrbit(){const seen=orb.layers.slice(0,orbitStep+1).reduce((a,b)=>a+b,0);$('#orbit-status').innerHTML=`Layer ${orbitStep}: <b>${fmt(seen)} / ${fmt(orb.blocks.length)}</b> blocks found. ${orbitStep===orb.layers.length-1?'The queue is exhausted; the orbit is complete.':'New blocks enter the queue for the next layer.'}`;$('#orbit-bars').innerHTML=bars(Object.fromEntries(orb.layers.slice(0,orbitStep+1).map((v,i)=>[i,v])),{gold:orbitStep});$('#orbit-next').disabled=orbitStep===orb.layers.length-1;}
 function mode(b){biplane=b;selected=[];blockIndex=0;$('#audit-result').innerHTML='';$('#witt-mode').classList.toggle('active',!b);$('#biplane-mode').classList.toggle('active',b);draw();resetOrbit();}
 if(state.n===11){$('#witt-mode').onclick=()=>mode(false);$('#biplane-mode').onclick=()=>mode(true);}$('#clear-points').onclick=()=>{selected=[];draw();};$('#example-subset').onclick=()=>{selected=model().blocks[blockIndex].slice(0,model().t);draw();};$('#block-range').oninput=e=>{blockIndex=+e.target.value;selected=[];draw();};$('#audit-design').onclick=()=>{const d=model(),r=M.auditDesign(d.blocks,d.n,d.t);const pass=biplane?r.distinct===55&&r.histogram[2]===55:r.pass;$('#audit-result').innerHTML=`<div class="result ${pass?'':'error'}"><b>${pass?'Verified':'Failed'}:</b> ${fmt(r.distinct)} / ${fmt(r.total)} subsets; multiplicity ${biplane?2:1} for every subset.</div>`;};$('#orbit-next').onclick=()=>{orbitStep=Math.min(orbitStep+1,orb.layers.length-1);showOrbit();};$('#orbit-all').onclick=()=>{orbitStep=orb.layers.length-1;showOrbit();};$('#orbit-reset').onclick=resetOrbit;draw();resetOrbit();};
 scenes.orders=()=>{const G=D.groups[state.n],chain=M.lectureChain(G,D.groups[11]),hasQuaternion=[11,12].includes(state.n);let level=hasQuaternion&&state.subgroup==='q8'?chain.length-1:0;
 $('#stage').innerHTML=head('04 / ORBIT–STABILIZER','Count a huge group without listing it.','Fix points one at a time. At each step, record the orbit of the next point under the current stabilizer. The product of these orbit sizes is the group order.')+
 `${hasQuaternion?'<div class="controls"><button id="show-q8" class="quiet">Why is the last nontrivial stabilizer Q₈? ↓</button></div>':''}<div class="chain">${chain.map((L,i)=>`<button data-level="${i}"><b>${L.orbit.length}</b><small>fix ${label(L.base)}</small></button>${i<chain.length-1?'<span>×</span>':''}`).join('')}<span>=</span><span class="formula">${fmt(G.order)}</span></div>
 <div class="grid"><section class="panel visual"><div class="panel-title"><h2 id="chain-title"></h2>${badge('Exact stabilizer data','build')}</div><div id="chain-figure"></div><div id="chain-stats"></div><div class="controls"><button id="chain-next">Fix this point →</button></div><p class="small muted">Gold points have already been fixed. Green points form the next orbit. The tree records the search that finds coset representatives.</p></section>
 <section class="panel"><h2>Membership by successive correction</h2><p class="compact">At base point b, find a stored representative t with t(b)=p(b). Replace p by t⁻¹p; the new permutation fixes b. Continue down the chain. The final remainder must be the identity.</p><div class="controls"><button id="sift-generator">Sift a generator</button><button id="sift-odd" class="quiet">Try a transposition</button></div><div id="sift-result"></div>${algorithm('Algorithm · Schreier–Sims and sifting','<p>A base is an ordered list of points with trivial pointwise stabilizer. Strong generators describe every stabilizer in the chain. A breadth-first orbit search supplies the transversals. Schreier generators t<sub>s(a)</sub>⁻¹ s t<sub>a</sub> fix the base point and generate its stabilizer.</p><p>The SageMath/GAP build obtains the stabilizers. The exported data include their generators and transversals; the browser independently checks every Schreier relation by sifting. This uses exact permutations, not a Monte Carlo estimate of the order.</p>','for each base point b:\n  if p(b) is outside the stored orbit: reject\n  p = inverse(transversal[p(b)]) * p\naccept exactly when p is the identity')}<div class="controls"><button id="audit-chain" class="quiet">Verify Schreier relations</button></div><div id="chain-audit"></div><p class="small">${note('orders')}</p></section></div>`;
 function draw(){const L=chain[level];document.querySelectorAll('[data-level]').forEach(el=>el.classList.toggle('active',+el.dataset.level===level));$('#chain-title').textContent=level===0?'Start with the whole group':'After fixing '+chain.slice(0,level).map(L=>label(L.base)).join(', ');$('#chain-figure').innerHTML=pointSVG(G.n,{selected:[L.base],block:L.orbit,fixed:chain.slice(0,level).map(L=>L.base),edges:L.tree.map(e=>e.slice(0,2))});$('#chain-stats').innerHTML=`<div class="metric-row">${metric(fmt(L.order),'current stabilizer')}${metric(L.orbit.length,'orbit size')}${metric(fmt(L.next_order),'next stabilizer')}</div>`;$('#chain-next').disabled=level===chain.length-1;}
 function showSift(p){const r=M.sift(p,chain);$('#sift-result').innerHTML=`<div class="result ${r.member?'':'gold'}"><b>${r.member?'Member':'Not a member'} of ${gname(state.n)}</b><div class="word">${esc(M.cycleText(p,i=>label(i)))}</div></div><div class="table-wrap"><table><thead><tr><th>Base</th><th>Image</th><th>Correction available?</th></tr></thead><tbody>${r.steps.map(s=>`<tr><td>${label(s.base)}</td><td>${label(s.image)}</td><td>${s.found?'Yes':'No — reject'}</td></tr>`).join('')}</tbody></table></div>${r.member?'<p class="small">Remainder: identity.</p>':''}`;}
 document.querySelectorAll('[data-level]').forEach(el=>el.onclick=()=>{level=+el.dataset.level;draw();});$('#chain-next').onclick=()=>{level++;draw();};$('#sift-generator').onclick=()=>showSift(G.generators[0]);$('#sift-odd').onclick=()=>{const p=M.identity(G.n);[p[0],p[1]]=[p[1],p[0]];showSift(p);};$('#audit-chain').onclick=()=>{const r=M.schreierAudit(chain);$('#chain-audit').innerHTML=`<div class="result"><b>${r.pass?'Verified':'Failed'}:</b> ${fmt(r.count)} Schreier relations reduce to the identity in the following stabilizers.</div>`;};draw();showSift(G.generators[0]);if(hasQuaternion){showQuaternion(G,()=>{level=chain.length-1;draw();});$('#show-q8').onclick=()=>{level=chain.length-1;draw();$('#q8-witness').scrollIntoView({block:'start'});};if(state.subgroup==='q8')requestAnimationFrame(()=>$('#q8-witness').scrollIntoView({block:'start'}));}};
 function showQuaternion(G,selectFinalLevel){
   const Q=M.quaternionStabilizer(G,D.groups[11]),cycles=p=>esc(M.cycleText(p,a=>label(a,G.n)));
   $('#stage').insertAdjacentHTML('beforeend',`<section class="panel" id="q8-witness" style="margin-top:22px"><div class="panel-title"><h2>Why the last nontrivial stabilizer is Q₈</h2>${badge('Eight explicit permutations')}</div>
   <p>Let K be the <b>pointwise stabilizer of ${mathset(Q.fixed,G.n)}</b> in ${gname(G.n)}. The chain gives |K| = 8. We still need to identify its group structure. The homework permutations i = ι and j = ȷ fix these points${G.n===12?' (extend them by fixing ∞)':''}.</p>
   <div class="grid equal"><div><div class="word">i = ${cycles(Q.i)}<br>j = ${cycles(Q.j)}<br>z = i² = ${cycles(Q.z)}</div><div class="formula small">i² = j² = z ≠ 1, &nbsp; z² = 1,<br>j⁻¹ij = i⁻¹.</div><p class="compact">These are the quaternion relations. They reduce every word to iᵃjᵇ with 0 ≤ a &lt; 4 and 0 ≤ b &lt; 2. The eight words below send 3 to eight different points, so all eight are distinct. Thus ⟨i,j⟩ ≅ Q₈.</p><p class="compact">The computation also checks that i and j belong to ${gname(G.n)} and fix ${mathset(Q.fixed,G.n)}. Hence ⟨i,j⟩ ⊆ K; since both have order 8, <b>K = ⟨i,j⟩ ≅ Q₈</b>.</p><p class="compact">The action on {3, …, 10} is regular. Fixing 3 as well leaves only the identity. So Q₈ is the last <em>nontrivial</em> stabilizer; the chain ends in 1.</p></div>
   <div class="visual panel"><label for="q8-element" class="small">Visualize a quaternion element</label><div class="controls"><select id="q8-element" aria-label="Quaternion element">${Q.entries.map((e,k)=>`<option value="${k}" ${k===1?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div id="q8-figure"></div><p id="q8-action" class="small"></p><p class="small muted">Gold points are fixed throughout. The selected point is the image of 3. Arrows show the selected permutation on all points.</p></div></div>
   <div class="table-wrap"><table id="q8-table"><thead><tr><th>Word</th><th>Image of 3</th><th>Order</th><th>Disjoint cycles</th></tr></thead><tbody>${Q.entries.map((e,k)=>`<tr data-q8-word="${k}"><td>${esc(e.name)}</td><td>${label(e.image,G.n)}</td><td>${e.order}</td><td class="word">${cycles(e.permutation)}</td></tr>`).join('')}</tbody></table></div>
   <div class="controls"><button id="q8-check">Verify relations and the full stabilizer</button><button id="q8-chain" class="quiet">Show this level in the chain ↑</button></div><div id="q8-result" aria-live="polite"></div>
   ${algorithm('Algorithm · a proof from eight permutations','<p>Compose arrays to check each relation on every point, and close {i,j} under multiplication. Compare the resulting eight elements with the eight normal forms; compute their images of 3 and their cycle orders. Sift each element through the ambient chain and through its final level. Verify the Schreier relations and the chain indices to identify the full point stabilizer.</p>'+(G.n===12?'<p>Here the displayed base is (∞,0,1,2,3), matching the lecture. A breadth-first search using the M₁₂ generators constructs the orbit and coset representatives at ∞. Below it, the M₁₁ chain is extended by fixing ∞. Ambient membership and all Schreier relations are checked, so the change from the stored base (0,1,2,3,4) is certified.</p>':''),'z = compose(i,i)\ncheck z == compose(j,j), z != 1, z*z == 1\ncheck inverse(j)*i*j == inverse(i)\nwords = [1,i,i²,i³,j,ij,i²j,i³j]\ncheck distinct images of 3; closure == words\ncheck words ⊆ K and |K| == 8')}
   </section>`);
   function drawQuaternion(){const k=+$('#q8-element').value,e=Q.entries[k];$('#q8-figure').innerHTML=pointSVG(G.n,{fixed:Q.fixed,selected:[e.image],permutation:e.permutation});$('#q8-action').textContent=e.name+': 3 → '+label(e.image,G.n)+'; element order '+e.order+'.';document.querySelectorAll('[data-q8-word]').forEach(row=>row.classList.toggle('selected',+row.dataset.q8Word===k));}
   $('#q8-element').onchange=drawQuaternion;drawQuaternion();
   $('#q8-chain').onclick=()=>{selectFinalLevel();$('#chain-title').scrollIntoView({block:'start'});};
   $('#q8-check').onclick=()=>{const r=M.quaternionStabilizer(G,D.groups[11]);$('#q8-result').innerHTML=`<div class="result ${r.pass?'':'error'}"><b>${r.pass?'Verified: K = ⟨i,j⟩ ≅ Q₈.':'Verification failed.'}</b> ${r.pass?'All relations hold on every point; the eight normal forms are exactly the generated subgroup. Their images of 3 are '+r.entries.map(e=>e.image).join(', ')+'. Ambient membership, the fixed frame, every Schreier relation and |K| = 8 all agree. Element orders: one identity, one involution, six elements of order 4. Fixing 3 next gives the identity.':'Failed checks: '+Object.entries(r.checks).filter(([,ok])=>!ok).map(([name])=>esc(name)).join(', ')+'.'}</div>`;};
 }
 scenes.sylow=()=>{const G=D.groups[state.n];let primeIndex=0;
 $('#stage').innerHTML=head('05 / LOCAL STRUCTURE','A simple group has rich p-subgroups.','Select a prime. Compare the Sylow subgroup with its normalizer, then enumerate only the small subgroup to see its element orders. The whole ambient group is never enumerated.')+
 `<section class="panel"><div class="panel-title"><h2>Sylow data for ${gname(state.n)}</h2>${badge('SageMath / GAP · exact','build')}</div><div class="table-wrap"><table id="sylow-table"><thead><tr><th>p</th><th class="num">|P|</th><th class="num">|N(P)|</th><th class="num">nₚ = |G| / |N(P)|</th><th>nₚ mod p</th></tr></thead><tbody>${G.sylows.map((P,i)=>`<tr data-select="${i}" tabindex="0" aria-label="Select Sylow ${P.p}-subgroup"><td><b>${P.p}</b></td><td class="num">${fmt(P.order)}</td><td class="num">${fmt(P.normalizer_order)}</td><td class="num">${fmt(P.number)}</td><td>${P.number%P.p}</td></tr>`).join('')}</tbody></table></div></section>
 <div class="grid" style="margin-top:22px"><section class="panel visual"><div class="panel-title"><h2 id="sylow-title"></h2>${badge('Subgroup computed live')}</div><div id="sylow-stats"></div><h3>How many elements of each order?</h3><div id="sylow-bars"></div><div id="sylow-insight"></div></section><section class="panel"><h2>From local structure to global counting</h2><div id="normalizer-explanation"></div><details class="algorithm"><summary>Explicit generators in the current coordinates</summary><div id="sylow-generators" class="word"></div></details>${algorithm('Algorithms · Sylow subgroup, normalizer, small closure','<p>The build asks GAP for SylowSubgroup(G,p) and Normalizer(G,P), and computes their orders through permutation-group algorithms. It exports actual subgroup generators, not just a lookup table. The browser closes those generators under multiplication (at most 1,024 elements here) and independently checks the order, element orders and membership in the ambient stabilizer chain.</p><p>The congruence nₚ ≡ 1 (mod p) is a consistency check. It does not determine the normalizer or prove the table by itself.</p>','P = SylowSubgroup(G,p)\nN = Normalizer(G,P)\nn_p = Size(G) / Size(N)')}<p class="small">${note('sylow')}</p></section></div>`;
 function draw(){const P=G.sylows[primeIndex],elements=M.groupClosure(P.generators,G.n,1100),hist=M.histogram(elements.map(M.order));document.querySelectorAll('#sylow-table tr[data-select]').forEach(el=>el.classList.toggle('selected',+el.dataset.select===primeIndex));$('#sylow-title').innerHTML=`A Sylow ${P.p}-subgroup of ${gname(G.n)}`;$('#sylow-stats').innerHTML=`<div class="metric-row">${metric(elements.length,'enumerated elements')}${metric(P.exponent,'exponent')}${metric(P.center_order,'center order')}</div>`;$('#sylow-bars').innerHTML=bars(hist);$('#sylow-generators').innerHTML=P.generators.map(g=>'<p>'+esc(M.cycleText(g,i=>label(i)))+'</p>').join('');let insight=P.abelian?`This Sylow subgroup is abelian. Its structure is ${esc(P.structure)}.`:`This Sylow subgroup is nonabelian. Its commutator subgroup has order ${P.derived_order}.`;if(G.n===11&&P.p===2)insight='Semidihedral SD₁₆: five involutions, rather than the nine in D₁₆. The relation srs⁻¹ = r³ changes the group.';if(G.n===11&&P.p===3)insight='C₃ × C₃ acts regularly on nine points and fixes a pair. Its 55 conjugates correspond to the 55 unordered pairs of the eleven-point set.';if(P.order===27&&P.exponent===3&&P.center_order===3)insight='The nonabelian group of order 27 and exponent 3: the Heisenberg group of upper unitriangular 3×3 matrices over 𝔽₃.';$('#sylow-insight').innerHTML=`<div class="result">${insight}</div><p class="small muted">GAP structure description: ${esc(P.structure)}. Its colon notation alone does not specify every semidirect-product action; the explicit permutations remove that ambiguity.</p>`;if(G.n===11&&P.p===2){const r=elements.find(a=>M.order(a)===8&&elements.some(b=>M.order(b)===2&&M.same(M.compose(b,M.compose(a,M.inverse(b))),M.power(a,3)))),s=elements.find(b=>M.order(b)===2&&M.same(M.compose(b,M.compose(r,M.inverse(b))),M.power(r,3)));const valid=M.groupClosure([r,s],11,17).length===16;$('#sylow-generators').innerHTML+=`<h3>Semidihedral presentation witness</h3><p>r = ${esc(M.cycleText(r,i=>label(i)))}<br>s = ${esc(M.cycleText(s,i=>label(i)))}</p><p>${valid?'Verified: r has order 8, s has order 2, srs⁻¹ = r³, and ⟨r,s⟩ has 16 elements.':'Verification failed.'}</p>`;}$('#normalizer-explanation').innerHTML=`<div class="formula">n<sub>${P.p}</sub> = ${fmt(G.order)} / ${fmt(P.normalizer_order)} = ${fmt(P.number)}</div><p class="compact">Conjugation acts transitively on the Sylow ${P.p}-subgroups. The stabilizer of P is N<sub>G</sub>(P), so orbit–stabilizer gives their number.</p><p class="compact">Orbits of P on the ${G.n} points have sizes <b>${P.orbit_sizes.join(', ')}</b>. Each size is a power of ${P.p}.</p><div class="result"><b>Browser check:</b> ${elements.length===P.order&&P.generators.every(g=>M.sift(g,G.chain).member)?'the generators belong to G and generate exactly '+fmt(P.order)+' elements.':'verification failed.'}</div>`;}
 document.querySelectorAll('#sylow-table tr[data-select]').forEach(el=>{el.onclick=()=>{primeIndex=+el.dataset.select;draw();};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};});draw();};
 scenes.triangles=()=>{const G=D.groups[state.n],T=G.triangle,[p,q,r]=T.orders;let which='xy';
 $('#stage').innerHTML=head('06 / AN INFINITE GROUP, A FINITE IMAGE','A triangle group maps onto '+gname(G.n)+'.','The displayed permutations satisfy the triangle relations and generate the full finite group. These two assertions are checked separately. The triangle group itself remains infinite.')+
 `<div class="grid"><section class="panel visual"><div class="panel-title"><h2>Inspect the finite image</h2>${badge('Exact witness')}</div><div class="controls"><button class="pill" data-tri="x">x · order ${p}</button><button class="pill" data-tri="y">y · order ${q}</button><button class="pill active" data-tri="xy">xy · order ${r}</button></div><div id="triangle-permutation"></div><p id="triangle-cycle" class="word"></p></section><section class="panel"><h2>Relations give a homomorphism</h2><div class="formula small">T′(${p},${q},${r}) = ⟨X,Y | X<sup>${p}</sup> = Y<sup>${q}</sup> = (XY)<sup>${r}</sup> = 1⟩<br>↓ &nbsp; X ↦ x, Y ↦ y<br>${gname(G.n)}</div><div class="result"><b>Generation verified:</b> |⟨x,y⟩| = ${fmt(T.image_order)} = |${gname(G.n)}|.<br><span class="small">Computed by GAP from this exact pair. Both permutations also sift into the displayed group.</span></div><p>Since 1/${p} + 1/${q} + 1/${r} &lt; 1, this is a hyperbolic triangle group. Its kernel has finite index ${fmt(G.order)} and is infinite.</p><p class="callout">A finite quotient is not a finite presentation of the same group.</p>${algorithm('Algorithm · finding and certifying a generating pair','<p>A seeded search forms words in the generators and extracts elements of small order by taking powers. Candidate pairs are filtered by the order of xy. Every accepted pair must generate a subgroup with the full group order. The search proposes a witness; the exact order calculation certifies it.</p><p>The browser recomputes the three element orders and checks membership. The included SageMath script reproduces the generation test. Exact images of the vertex rotations imply a torsion-free kernel, by the triangle-group torsion theorem proved in the earlier lecture.</p>')}<p class="small">${note('triangles')}</p></section></div>
 <section class="panel"><div class="panel-title"><h2>A surface with ${gname(G.n)} symmetry</h2>${badge('Consequence of the triangle theorem','cited')}</div><div class="metric-row">${metric(fmt(T.surface_genus),'surface genus')}${metric(fmt(2*G.order),'reflection triangles')}${metric(fmt(G.order),'covering degree')}</div><p class="compact">The torsion-free kernel gives a closed surface with 2 − 2g = |G|(1/${p} + 1/${q} + 1/${r} − 1). This surface has an action of ${gname(G.n)}; no minimal-genus or full-automorphism-group claim is being made. The covering degree is the group order, not the ${G.n}-point permutation degree.</p><p class="small"><a href="../triangle-quotients/">Compare with the course’s triangle-quotient visualization ↗</a></p></section>`;
 function draw(){const a=which==='x'?T.x:which==='y'?T.y:M.compose(T.x,T.y);document.querySelectorAll('[data-tri]').forEach(el=>el.classList.toggle('active',el.dataset.tri===which));$('#triangle-permutation').innerHTML=pointSVG(G.n,{permutation:a});$('#triangle-cycle').textContent=which+' = '+M.cycleText(a,i=>label(i));}
 document.querySelectorAll('[data-tri]').forEach(el=>el.onclick=()=>{which=el.dataset.tri;draw();});draw();};
 scenes.codes=()=>{let name=state.n<20?(state.n===12?'ternary12':'ternary11'):(state.n===23?'binary23':'binary24'),sentIndex=0,received=[],decoded=null;
 $('#stage').innerHTML=head('07 / FROM A DESIGN TO A CODE','Change a few symbols. Recover the word.','Enumerate a small vector space, measure Hamming distance, and decode by nearest-word search. A perfect code fills the entire ambient space with disjoint error balls.')+
 `<div class="controls"><label for="code-select">Code</label><select id="code-select"><option value="ternary11">Ternary [11,6,5] · two-error correction</option><option value="ternary12">Extended ternary [12,6,6]</option><option value="binary23">Binary [23,12,7] · three-error correction</option><option value="binary24">Extended binary [24,12,8]</option></select>${badge('All codewords generated live')}</div>
 <div class="grid"><section class="panel"><h2 id="code-title"></h2><label class="small" for="sent-range">Choose a codeword to send</label><input id="sent-range" type="range" min="0" value="0"><div class="code-label">SENT WORD <span id="sent-index"></span></div><div id="sent-word" class="code-row"></div><div class="code-label">RECEIVED WORD · CLICK A COORDINATE TO ALTER IT</div><div id="received-word" class="code-row"></div><div class="controls"><button id="decode">Decode</button><button id="inject-errors" class="quiet">Add correctable errors</button><button id="too-many-errors" class="quiet">Try one extra error</button><button id="clear-errors" class="quiet">Reset</button></div><div id="decode-result"></div><p class="small muted">Orange coordinates differ from the sent word. The decoder sees only the received word; the sent word is shown here so we can check its answer.</p></section>
 <section class="panel visual"><h2>Weight distribution</h2><div id="code-metrics" class="metric-row"></div><div id="weight-bars"></div><div id="sphere-packing"></div>${algorithm('Algorithms · row reduction, enumeration, decoding','<p>Gaussian elimination over 𝔽₂ or 𝔽₃ finds a basis. Enumerate all qᵏ linear combinations. For each received word, scan every codeword and count differing coordinates; retain all minimizers, including ties. At most 4,096 × 24 symbol comparisons are needed here.</p><p>This is deliberately transparent nearest-word decoding. Production decoders can use syndromes and precomputed error tables. Beyond the guaranteed radius, a unique nearest codeword need not be the transmitted one.</p>','best = min(distance(y,c) for c in codewords)\nwinners = [c for c in codewords if distance(y,c)==best]')}<p class="small">${note('codes')}</p></section></div>
 <section class="panel"><div class="panel-title"><h2>Recover the design from codeword supports</h2><button id="code-supports" class="quiet">Check supports</button></div><p id="support-description" class="compact"></p><div id="support-result"></div><details class="algorithm"><summary>Generator matrix and construction</summary><p id="code-construction" class="compact"></p><pre id="code-basis"></pre></details></section>`;
 function reset(){const C=D.codes[name],words=getWords(name);sentIndex=0;received=[...words[0]];decoded=null;$('#code-select').value=name;$('#sent-range').max=words.length-1;$('#sent-range').value=0;$('#code-title').textContent=`[${C.n}, ${C.k}, ${C.minimum_distance}] over 𝔽${C.q===2?'₂':'₃'}`;$('#code-metrics').innerHTML=metric(fmt(words.length),'codewords')+metric(C.minimum_distance,'minimum distance');const hist=M.histogram(words.map(M.weight));$('#weight-bars').innerHTML=bars(hist);const radius=Math.floor((C.minimum_distance-1)/2),volume=Array.from({length:radius+1},(_,i)=>M.choose(C.n,i)*(C.q-1)**i).reduce((a,b)=>a+b,0),perfect=volume*words.length===C.q**C.n;$('#sphere-packing').innerHTML=`<div class="result ${perfect?'':'gold'}"><b>${perfect?'Perfect':'Not perfect'} at radius ${radius}.</b><br>${fmt(words.length)} codewords × ${fmt(volume)} words per ball ${perfect?'=':'<'} ${fmt(C.q**C.n)} ambient words.</div>`;$('#code-basis').textContent=C.basis.map(r=>r.join(' ')).join('\n');$('#code-construction').textContent=C.q===3?'Rows of 2A−J over 𝔽₃, where A is the eleven-point residue-biplane incidence matrix. The twelve-coordinate version appends the coordinate sum. The displayed basis is obtained by row reduction.':'Use the cyclic polynomial g(t)=t¹¹+t⁹+t⁷+t⁶+t⁵+t+1. The rows are tʲg(t), 0≤j<12; the 24-coordinate version appends the parity bit. These are the exact large-group coordinates used throughout this presentation.';$('#support-description').textContent=C.q===3?`The minimum-weight words occur in pairs c and −c. Removing duplicate supports gives ${C.n===11?'66 pentads of S(4,5,11)':'132 hexads of S(5,6,12)'}. Plain coordinate permutations need not preserve the ternary code: signed lifts are needed.`:C.n===24?'The 759 weight-eight words are the octads of S(5,8,24). They span the code. Deriving at the parity coordinate gives W₂₃; deriving again at 22 gives W₂₂.':'The 253 weight-seven words are the blocks of S(4,7,23). Appending parity turns them into octads containing ∞.';$('#support-result').innerHTML='';draw();}
 function cells(w,kind,sent){return w.map((v,i)=>`<${kind==='received'?'button':'span'} class="code-cell ${v!==sent[i]?'err':''}" ${kind==='received'?`data-symbol="${i}" aria-label="Coordinate ${i}, value ${v}; click to change"`:''}>${v}<small>${i===11&&w.length===12||i===23&&w.length===24?'∞':i}</small></${kind==='received'?'button':'span'}>`).join('');}
 function draw(){const C=D.codes[name],words=getWords(name),sent=words[sentIndex];$('#sent-index').textContent=`${sentIndex+1} / ${words.length}`;$('#sent-word').innerHTML=cells(sent,'sent',sent);$('#received-word').innerHTML=cells(received,'received',sent);document.querySelectorAll('[data-symbol]').forEach(el=>el.onclick=()=>{const i=+el.dataset.symbol;received[i]=(received[i]+1)%C.q;decoded=null;draw();});const errors=M.distance(sent,received),radius=Math.floor((C.minimum_distance-1)/2);if(!decoded){$('#decode-result').innerHTML=`<div class="result ${errors>radius?'gold':''}">${errors} altered coordinate${errors===1?'':'s'}. Guaranteed correction radius: ${radius}.</div>`;return;}const recovered=decoded.winners.length===1&&decoded.winners[0]===sentIndex;$('#decode-result').innerHTML=`<div class="result ${recovered?'':'gold'}"><b>${decoded.winners.length===1?(recovered?'Recovered the sent word.':'Unique nearest word, but not the sent word.'):'Ambiguous: '+decoded.winners.length+' equally near codewords.'}</b><br>Minimum distance from received word: ${decoded.minimum}. Scanned all ${fmt(words.length)} codewords.</div>${decoded.winners.length===1?'<div class="code-label">DECODED WORD</div><div class="code-row">'+cells(words[decoded.winners[0]],'decoded',sent)+'</div>':''}`;}
 $('#code-select').onchange=e=>{name=e.target.value;reset();};$('#sent-range').oninput=e=>{sentIndex=+e.target.value;received=[...getWords(name)[sentIndex]];decoded=null;draw();};$('#clear-errors').onclick=()=>{received=[...getWords(name)[sentIndex]];decoded=null;draw();};$('#decode').onclick=()=>{decoded=M.decode(received,getWords(name));draw();};function inject(extra){const C=D.codes[name],words=getWords(name),r=Math.floor((C.minimum_distance-1)/2),small=words.find(w=>M.weight(w)===C.minimum_distance);received=[...words[sentIndex]];const positions=small.map((x,i)=>x?i:-1).filter(i=>i>=0);for(const i of positions.slice(0,r+(extra?1:0)))received[i]=(received[i]+small[i])%C.q;decoded=null;draw();}$('#inject-errors').onclick=()=>inject(false);$('#too-many-errors').onclick=()=>inject(true);$('#code-supports').onclick=()=>{const C=D.codes[name],words=getWords(name),supports=[...new Set(words.filter(w=>M.weight(w)===C.minimum_distance).map(w=>w.map((x,i)=>x?i:-1).filter(i=>i>=0).join(',')))].map(s=>s.split(',').map(Number)),n=C.n,t=n===11?4:n===12?5:n===23?4:5,result=M.auditDesign(supports,n,t),G=D.groups[n];const equal=supports.length===G.blocks.length&&supports.every(B=>G.blocks.some(A=>M.same(A,B)));$('#support-result').innerHTML=`<div class="result"><b>${result.pass&&equal?'Verified':'Failed'}:</b> ${supports.length} distinct supports match the displayed design; all ${fmt(result.total)} defining subsets occur exactly once.</div>`;};reset();};
 scenes.representations=()=>{const G=D.groups[state.n];let classIndex=1;const inner=G.classes.reduce((s,C)=>s+C.size*(C.fixed-1)**2,0)/G.order;
 $('#stage').innerHTML=head('08 / LINEAR ACTIONS','Count fixed points. Read off a character.','Every permutation action gives a linear representation. Remove the constant vectors: the remaining module has dimension n−1 and character χ(g) = number of fixed points − 1.')+
 `<div class="grid"><section class="panel visual"><div class="panel-title"><h2>The augmentation module of ${gname(G.n)}</h2>${badge('Character values computed live')}</div><div id="character-figure"></div><div id="character-stats" class="metric-row"></div><label for="class-select" class="small">Choose a conjugacy class</label><select id="class-select" style="width:100%">${G.classes.map((C,i)=>`<option value="${i}">Class ${i+1} · order ${C.order} · size ${fmt(C.size)}</option>`).join('')}</select><p id="class-cycle" class="word"></p></section><section class="panel"><h2>Double transitivity implies irreducibility</h2><div class="formula small">U = {z ∈ ℂ<sup>${G.n}</sup> : ∑zᵢ = 0}<br>dim U = ${G.n-1}<br>χ<sub>U</sub>(g) = Fix(g) − 1</div><p class="compact">A matrix commuting with a doubly transitive permutation group has a constant diagonal and a constant off-diagonal. It is aI+bJ, so its restriction to U is scalar. An invariant proper subspace would give a nonscalar orthogonal projection, a contradiction.</p><div class="result"><b>Character check:</b> ⟨χ,χ⟩ = (1 / ${fmt(G.order)}) ∑<sub>classes C</sub> |C| · χ(C)² = <b>${inner}</b>.</div><p class="compact">Class representatives and sizes are computed by GAP. The fixed-point counts and the inner product are recomputed here. Class numbers are local labels, not ATLAS class names.</p>${algorithm('Algorithms · conjugacy classes and permutation characters','<p>GAP computes conjugacy classes and centralizers in the permutation group. The class equation checks that their sizes sum to |G|. In the browser, count fixed points of each representative and subtract 1; weight the squared character values by class sizes. This avoids constructing dense representation matrices.</p>')}<p class="small">${note('representations')}</p></section></div>
 ${G.n===11?`<section class="panel"><div class="panel-title"><h2>Two more realizations of M₁₁</h2><button id="module-check" class="quiet">Check the signed lifts</button></div><div class="grid equal"><div><h3>Twelve biplanes on eleven points</h3><p class="compact">The orbit of the residue biplane contains twelve biplanes. Each pentad appears in exactly two of them. This gives another faithful permutation action, now of degree 12, and an irreducible augmentation module of dimension 11.</p><label class="small" for="biplane-range">Inspect one of the twelve incidence matrices</label><input id="biplane-range" type="range" min="0" max="11" value="0"><div id="biplane-matrix" class="matrix" style="grid-template-columns:repeat(11,1fr)"></div><p id="biplane-caption" class="small muted"></p></div><div><h3>Five dimensions over 𝔽₃</h3><p class="compact">The sum-zero subcode C₀ equals C⊥ and has dimension 5. Ordinary permutations i and j do not preserve C. Signed lifts do: T(eᵢ)=εᵢe<sub>g(i)</sub>.</p><div class="table-wrap"><table><thead><tr><th>Generator</th><th>Negative coordinate signs</th></tr></thead><tbody>${['r','i','j'].map((s,i)=>`<tr><td>${s}</td><td>${D.small_witnesses.signed_lifts[i].join(', ')||'none'}</td></tr>`).join('')}</tbody></table></div><div id="module-result"></div><p class="compact">The lifted action on C₀ has orbit sizes 1, 132, 110. An invariant subspace must be a union of whole orbits containing zero, and must have a power of 3 elements. Only 1 and 243 are possible: the module is irreducible.</p></div></div></section>
 <section class="panel"><h2>The first exceptional invariant</h2><div class="formula small">F(z) = ∑<sub>pentads B</sub> ∏<sub>i∈B</sub> zᵢ &nbsp; · &nbsp; Q = 7F − e₅</div><p class="compact">Four-fold transitivity makes every invariant of degree at most four symmetric. Degree five is the first place the pentads give a new invariant. Each four-set occurs once, so (∑∂/∂zᵢ)F=e₄ and (∑∂/∂zᵢ)Q=0. Thus Q is unchanged by translating all coordinates together.</p><button id="invariant-check" class="quiet">Verify the derivative identity</button><div id="invariant-result"></div><p class="small muted">These are direct consequences of the design. They do not identify the full projective automorphism group of the quintic hypersurface.</p></section>`:''}`;
 function draw(){const C=G.classes[classIndex],p=C.representative;$('#class-select').value=classIndex;$('#character-figure').innerHTML=pointSVG(G.n,{permutation:p,fixed:p.map((j,i)=>j===i?i:-1).filter(i=>i>=0)});$('#character-stats').innerHTML=metric(C.fixed,'fixed points')+metric(C.fixed-1,'character value')+metric(fmt(C.size),'class size');$('#class-cycle').textContent=M.cycleText(p,i=>label(i));}
 $('#class-select').onchange=e=>{classIndex=+e.target.value;draw();};if(G.n===11){function biplaneMatrix(i){const B=D.small_witnesses.biplanes[i];$('#biplane-matrix').innerHTML=B.flatMap(row=>Array.from({length:11},(_,j)=>`<span class="${row.includes(j)?'on':''}" title="Row ${mathset(row)}, column ${j}">${row.includes(j)?'1':'0'}</span>`)).join('');$('#biplane-caption').textContent=`Biplane ${i+1} / 12. Rows are blocks; columns are points 0,…,10.`;}$('#biplane-range').oninput=e=>biplaneMatrix(+e.target.value);biplaneMatrix(0);$('#module-check').onclick=()=>{const words=getWords('ternary11'),keys=new Set(words.map(w=>w.join(',')));let plain=[],signed=[];G.generators.forEach((g,j)=>{const T=(w,sign)=>{const v=Array(11).fill(0);w.forEach((x,i)=>v[g[i]]=x*(sign&&D.small_witnesses.signed_lifts[j].includes(i)?2:1)%3);return keys.has(v.join(','));};plain.push(words.every(w=>T(w,false)));signed.push(words.every(w=>T(w,true)));});$('#module-result').innerHTML=`<div class="result">Plain r, i, j preserve C: <b>${plain.map(x=>x?'yes':'no').join(', ')}</b>.<br>Signed r, i, j preserve C: <b>${signed.map(x=>x?'yes':'no').join(', ')}</b>.<br><span class="small">All 729 codewords checked for each lift. The build separately checks that the lifted group has order 7,920 and computes the three module orbits.</span></div>`;};$('#invariant-check').onclick=()=>{const r=M.auditDesign(G.blocks,11,4);$('#invariant-result').innerHTML=`<div class="result">${r.pass?'Verified':'Failed'}: every one of the ${r.total} squarefree quartic monomials occurs once in ∑∂F/∂zᵢ. Each occurs seven times in ∑∂e₅/∂zᵢ, so the derivative of 7F−e₅ is zero.</div>`;};}draw();};
 scenes.methods=()=>{$('#stage').innerHTML=head('09 / WHAT HAS BEEN CHECKED','Make the computation part of the proof.','The presentation separates live arithmetic, exact data generated with SageMath/GAP, and mathematical theorems. Every displayed large-group result can be regenerated from the included source.')+
 `<div class="grid equal"><section class="panel"><h2>A reproducible chain of evidence</h2><ol class="step-list"><li><b>Construct.</b> Use the homework generators for M₁₁ and M₁₂. Build the binary Golay code from its cyclic generator polynomial; compute its permutation automorphism group, then fix ∞ and 22 to obtain M₂₃ and M₂₂.</li><li><b>Calculate.</b> Compute stabilizer chains, Sylow subgroups and normalizers, conjugacy classes, and actual generating triangle pairs using exact permutations.</li><li><b>Check.</b> Enumerate the small codes and block sets. Verify every design incidence, generator membership, Schreier relation, class equation and code parameter. Check the subgroup generated by each triangle pair has the full order.</li><li><b>Explain.</b> Use orbit–stabilizer, normal subgroup arguments, representation theory and the sphere-packing argument in the notes to interpret the results.</li></ol><div class="controls"><button id="run-audit">Run all browser checks</button><a class="button quiet" href="data/verification.json">Build report ↗</a></div><div id="all-audit"></div></section>
 <section class="panel"><h2>Choose the algorithm to fit the object</h2><div class="table-wrap"><table><thead><tr><th>Object</th><th>Method</th><th>Largest object here</th></tr></thead><tbody><tr><td>One permutation</td><td>Array composition, cycle traversal</td><td>24 points</td></tr><tr><td>Block orbit</td><td>Breadth-first search + hash set</td><td>759 blocks</td></tr><tr><td>Design</td><td>Subset incidence dictionary</td><td>42,504 five-sets</td></tr><tr><td>Ambient group</td><td>Stabilizer chain and sifting</td><td>244,823,040 elements, not listed</td></tr><tr><td>Sylow subgroup</td><td>Small closure enumeration</td><td>1,024 elements</td></tr><tr><td>Code</td><td>Row reduction + qᵏ combinations</td><td>4,096 words</td></tr><tr><td>Code symmetry</td><td>Partition backtracking</td><td>24 coordinates</td></tr></tbody></table></div>${algorithm('Why partition backtracking helps','<p>A naive automorphism search would try 24! coordinate permutations. The code-automorphism algorithm refines partitions using code structure and backtracks only over compatible choices; already-found symmetries prune equivalent branches. SageMath supplies this computation. The returned generators are checked against the octads, which span the code, and the stabilizer chain gives the group order.</p>')}<p class="small muted">Build environment: SageMath ${esc(D.sage)} · GAP ${esc(D.gap)}. Integer and finite-field arithmetic throughout. The browser has no network or library dependency.</p></section></div>
 <section class="panel"><h2>Reproduce and inspect</h2><pre class="word">sage -python scripts/generate_mathieu.py
node tests/verify_data.cjs
python3 -m http.server 8000</pre><p class="compact">Run these commands from the downloaded demonstration folder. Open localhost:8000, or open index.html directly for offline use. A headless browser test is also included; it requires Playwright and a Chromium browser.</p><div class="controls"><a class="button" href="source.zip" download>All sources ↓</a><a class="button quiet" href="scripts/generate_mathieu.py">SageMath computation</a><a class="button quiet" href="core.js">Browser algorithms</a><a class="button quiet" href="notes/math611_lecture_9_m11_ver2.tex">Editable lecture source</a></div><p class="small">${note('methods')}</p></section>
 <section class="panel"><h2>Sources and the limits of the computation</h2><p class="compact">The finite checks prove statements about the displayed permutations, designs and codes. Identification with the classical Mathieu groups uses the cited constructions. Simplicity of M₁₁ and M₁₂ is proved in the notes; the simplicity of the large groups is cited. A triangle pair proves a quotient, not a complete finite presentation. The surface interpretation uses the hyperbolic triangle-group theorem.</p><ol class="source-list"><li>Mathieu, <a href="https://www.numdam.org/item/JMPA_1861_2_6__241_0/">1861 memoir</a> and <a href="https://www.numdam.org/item/JMPA_1873_2_18__25_0/">1873 paper on 24 quantities</a>.</li><li>Witt, <a href="https://doi.org/10.1007/BF02948947">Die 5-fach transitiven Gruppen von Mathieu</a> and <a href="https://doi.org/10.1007/BF02948948">Über Steinersche Systeme</a> (1938).</li><li>ATLAS of Finite Group Representations: <a href="https://brauer.maths.qmul.ac.uk/Atlas/spor/M11/">M₁₁</a>, <a href="https://brauer.maths.qmul.ac.uk/Atlas/spor/M12/">M₁₂</a>, <a href="https://brauer.maths.qmul.ac.uk/Atlas/spor/M22/">M₂₂</a>, <a href="https://brauer.maths.qmul.ac.uk/Atlas/spor/M23/">M₂₃</a>, <a href="https://brauer.maths.qmul.ac.uk/Atlas/spor/M24/">M₂₄</a>.</li><li>H. Cuypers, <a href="https://www.win.tue.nl/~hansc/mathieu.pdf">The Mathieu groups and their geometries</a>.</li><li>Conway–Elkies–Martin, <a href="https://arxiv.org/abs/math/0508630">The Mathieu group M₁₂ and its pseudogroup extension M₁₃</a>.</li><li>Golay, <a href="https://pierre-hyvernat.apps.math.cnrs.fr/data/Enseignement/2223/info602/TP-Golay/golay_paper.pdf">Notes on digital coding</a> (1949), original paper.</li><li><a href="https://doc.sagemath.org/html/en/reference/coding/sage/coding/linear_code.html">SageMath linear-code algorithms</a>; <a href="https://docs.gap-system.org/doc/ref/chap43.html">GAP permutation-group algorithms</a>.</li><li>Gómez-Gonzáles–Sutherland–Wolfson, <a href="https://arxiv.org/abs/2310.09375">Generalized versality, special points, and resolvent degree for the sporadic groups</a> (2024), Appendix A, for the Molien series.</li></ol></section>`;
 $('#run-audit').onclick=()=>{const results=[];for(const [n,G] of Object.entries(D.groups)){const design=M.auditDesign(G.blocks,G.n,G.t),chain=M.schreierAudit(G.chain),orders=G.triangle.orders,actual=[M.order(G.triangle.x),M.order(G.triangle.y),M.order(M.compose(G.triangle.x,G.triangle.y))];results.push([`M${n}: ${fmt(design.total)} design subsets; ${fmt(chain.count)} Schreier relations; triangle orders`,design.pass&&chain.pass&&M.same(orders,actual)&&G.classes.reduce((s,C)=>s+C.size,0)===G.order]);}for(const [name,C] of Object.entries(D.codes)){const words=getWords(name),hist=M.histogram(words.map(M.weight));results.push([`${name}: all ${fmt(words.length)} words and weight counts`,Object.keys(hist).every(w=>hist[w]===C.weight_distribution[w])&&Object.keys(hist).length===Object.keys(C.weight_distribution).length]);}$('#all-audit').innerHTML=`<div class="result"><b>${results.every(r=>r[1])?'All checks passed':'A check failed'}</b><ul class="small">${results.map(([s,ok])=>`<li>${ok?'✓':'✗'} ${s}</li>`).join('')}</ul></div>`;};};
 const basePermScene=scenes.permutations;
 scenes.permutations=()=>{basePermScene();if(state.n!==11)return;$('#stage').insertAdjacentHTML('beforeend',`<section class="panel"><div class="panel-title"><h2>The finite witness in the simplicity proof</h2><button id="simplicity-check" class="quiet">Verify the witness</button></div><p class="compact">Let a=ρ and b=ιρι⁻¹. Both are eleven-cycles. The following words recover the other homework generators:</p><div class="word">ι = ${esc(D.small_witnesses.simplicity.iota_word)}<br>ȷ = ${esc(D.small_witnesses.simplicity.jmath_word)}</div><div id="simplicity-result"></div><p class="small">This calculation supplies the normal-generation input. The normal-subgroup argument is in ${note('simplicity','the simplicity proof')}.</p></section>`);$('#simplicity-check').onclick=()=>{const W=D.small_witnesses.simplicity,gens=[W.a,W.b],a=M.parseWord(W.iota_word,['a','b'],gens,11).permutation,b=M.parseWord(W.jmath_word,['a','b'],gens,11).permutation,closure=M.groupClosure(gens,11,8000);const ok=M.same(a,D.groups[11].generators[1])&&M.same(b,D.groups[11].generators[2])&&closure.length===7920;$('#simplicity-result').innerHTML=`<div class="result"><b>${ok?'Verified':'Failed'}:</b> both identities agree on all eleven letters, and ⟨a,b⟩ has ${fmt(closure.length)} elements. This small group can be enumerated; the large-group chapters use stabilizer chains.</div>`;};};
 const baseDesignScene=scenes.designs;
 scenes.designs=()=>{baseDesignScene();if(state.n===11){const R=D.small_witnesses.rigidity;$('#stage').insertAdjacentHTML('beforeend',`<section class="panel"><div class="panel-title"><h2>Why four fixed points force the identity</h2><button id="rigidity-check" class="quiet">Test the remaining 6! permutations</button></div><p class="compact">Fix 0, 1, 2, 3. The unique pentad through them is ${mathset(R.forced_block)}, so its fifth point is fixed too. Only the six other points ${mathset(R.remaining)} can move. Test their 720 possible permutations against the pentads.</p><div id="rigidity-result"></div><p class="small">This computes the pointwise stabilizer in the <em>full design automorphism group</em>, not just in the subgroup generated by the homework permutations. Combined with 4-transitivity, it proves that these are the same group.</p></section>`);$('#rigidity-check').onclick=()=>{const G=D.groups[11],keys=new Set(G.blocks.map(B=>B.join(','))),remaining=R.remaining;let tested=0,passed=0;function visit(prefix,rest){if(rest.length){for(const i of rest)visit([...prefix,i],rest.filter(j=>j!==i));return;}tested++;const g=M.identity(11);remaining.forEach((v,i)=>g[v]=prefix[i]);if(G.blocks.every(B=>keys.has(M.image(g,B).join(','))))passed++;}visit([],remaining);$('#rigidity-result').innerHTML=`<div class="result"><b>${tested} candidates tested; ${passed} survives.</b> The identity is the only automorphism fixing the frame.</div>`;};}
 if(state.n===12){$('#stage').insertAdjacentHTML('beforeend',`<section class="panel"><div class="panel-title"><h2>The homework construction uses a smaller group</h2><button id="projective-check" class="quiet">Build the PSL₂(𝔽₁₁) orbit</button></div><p class="compact">Start from H = {1,3,4,5,9,∞}. Use only z ↦ z+1 and z ↦ −1/z. These generate PSL₂(𝔽₁₁), of order 660. Their orbit already gives all 132 hexads; M₁₂ supplies many more symmetries of the same design.</p><div id="projective-result"></div></section>`);$('#projective-check').onclick=()=>{const P=D.small_witnesses.projective,orbit=M.blockOrbit(P.seed,P.generators),keys=new Set(D.groups[12].blocks.map(B=>B.join(','))),good=orbit.blocks.length===132&&orbit.blocks.every(B=>keys.has(B.join(',')));$('#projective-result').innerHTML=`<div class="result"><b>${good?'Verified':'Failed'}:</b> the smaller group reaches ${orbit.blocks.length} distinct hexads, exactly the displayed design.</div><div>${bars(Object.fromEntries(orbit.layers.map((v,i)=>[i,v])))}</div>`;};}};
 $('#group-select').onchange=e=>navigate(state.scene,+e.target.value);
 $('#previous').onclick=()=>{const i=chapters.findIndex(c=>c[0]===state.scene);if(i>0)navigate(chapters[i-1][0]);};$('#next').onclick=()=>{const i=chapters.findIndex(c=>c[0]===state.scene);if(i<chapters.length-1)navigate(chapters[i+1][0]);};
 function present(){document.body.classList.toggle('present-mode');$('#present').textContent=document.body.classList.contains('present-mode')?'Exit present':'Present';}
 $('#present').onclick=present;
 document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowRight'){$('#next').click();e.preventDefault();}else if(e.key==='ArrowLeft'){$('#previous').click();e.preventDefault();}else if(e.key.toLowerCase()==='f')present();});
 window.addEventListener('hashchange',render);render();
})();
